h3 { font-size: clamp(1.5rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }
p { margin-bottom: var(--space-sm); font-size: 1.125rem; color: var(--text-secondary); }

/* Layout Utilities */
.container {
  width: 100%;
  max-width: var(--container-width);
  margin: 0 auto;
  padding: 0 var(--space-md);
}

.section {
  padding: var(--space-xl) 0;
}

.section-bg-surface {
  background-color: var(--bg-surface);
}

.text-center { text-align: center; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 1.5rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  text-align: center;
}

.btn-primary {
  background-color: var(--brand-primary);
  color: var(--bg-white) !important;
}

.btn-primary:hover {
  background-color: var(--brand-primary-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background-color: var(--bg-white);
  color: var(--brand-primary) !important;
  border: 2px solid var(--bg-white);
}

.btn-secondary:hover {
  background-color: rgba(255,255,255,0.9);
  transform: translateY(-2px);
}

.btn-outline {
  background-color: transparent;
  color: var(--brand-secondary) !important;
  border: 2px solid var(--brand-secondary);
}

.btn-outline:hover {
  background-color: var(--brand-secondary);
  color: var(--bg-white) !important;
}

/* Header & Navigation */
.top-bar {
  background-color: var(--brand-secondary);
  color: var(--text-light);
  padding: var(--space-xs) 0;
  font-size: 0.875rem;
}

.top-bar .container {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-sm);
}

.top-bar a {
  color: var(--text-light);
  opacity: 0.8;
}

.top-bar a:hover {
  opacity: 1;
}

header {
  background-color: var(--bg-white);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 80px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--brand-primary);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo span {
  color: var(--brand-secondary);
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.nav-links {
  display: flex;
  gap: var(--space-md);
}

.nav-links a {
  color: var(--text-primary);
  font-weight: 500;
  font-size: 0.95rem;
}

.nav-links a:hover {
  color: var(--brand-primary);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  color: var(--text-primary);
  cursor: pointer;
}

/* Hero Section */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background-image: url('https://images.unsplash.com/photo-1469571486292-0ba58a3f068b?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80');
  background-size: cover;
  background-position: center;
  color: var(--text-light);
}

.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(to right, rgba(27, 58, 92, 0.9) 0%, rgba(27, 58, 92, 0.6) 100%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 700px;
}

.hero h1 {
  color: var(--text-light);
}

.hero p {
  color: var(--text-light);
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
  opacity: 0.9;
}

.hero-actions {
  display: flex;
  gap: var(--space-sm);
}

/* Mission Section */
.mission-text {
  max-width: 800px;
  margin: 0 auto;
  font-size: 1.25rem;
}

/* Impact Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-md);
}

.stat-card {
  text-align: center;
  padding: var(--space-md);
}

.stat-number {
  display: block;
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--brand-primary);
  line-height: 1;
  margin-bottom: var(--space-xs);
}

.stat-label {
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--brand-secondary);
}

/* Programs Accordion */
.programs-container {
  max-width: 800px;
  margin: 0 auto;
}

.accordion-item {
  border: 1px solid var(--bg-surface-alt);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-sm);
  background-color: var(--bg-white);
  overflow: hidden;
}

.accordion-header {
  padding: 1.5rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--bg-white);
  border: none;
  width: 100%;
  text-align: left;
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--brand-secondary);
  transition: background-color 0.2s ease;
}

.accordion-header:hover {
  background-color: var(--bg-surface);
}

.accordion-icon {
  transition: transform 0.3s ease;
}

.accordion-item.active .accordion-icon {
  transform: rotate(180deg);
}

.accordion-content {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s ease-out;
}

.accordion-inner {
  overflow: hidden;
  padding: 0 1.5rem;
}

.accordion-item.active .accordion-content {
  grid-template-rows: 1fr;
}

.accordion-item.active .accordion-inner {
  padding-bottom: 1.5rem;
}

/* Get Involved */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-md);
}

.card {
  background: var(--bg-white);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
  border: 1px solid var(--bg-surface-alt);
  display: flex;
  flex-direction: column;
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.card h3 {
  color: var(--brand-secondary);
}

.card .btn {
  margin-top: auto;
  align-self: flex-start;
}

/* News Carousel */
.carousel-wrapper {
  position: relative;
  margin: 0 calc(var(--space-md) * -1);
  padding: 0 var(--space-md);
}

.carousel-track {
  display: flex;
  gap: var(--space-md);
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding-bottom: var(--space-md);
  scrollbar-width: none;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.news-card {
  flex: 0 0 calc(33.333% - 1.33rem);
  scroll-snap-align: start;
  background: var(--bg-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--bg-surface-alt);
}

.news-content {
  padding: 1.5rem;
}

.news-card h4 {
  color: var(--brand-secondary);
  margin-bottom: 0.5rem;
}

.news-card p {
  font-size: 1rem;
  margin-bottom: 0;
}

.carousel-controls {
  display: flex;
  justify-content: flex-end;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--brand-secondary);
  background: var(--bg-white);
  color: var(--brand-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
}

.carousel-btn:hover {
  background: var(--brand-secondary);
  color: var(--bg-white);
}

/* Donate CTA Area */
.donate-cta-section {
  background-color: var(--brand-secondary);
  color: var(--text-light);
}

.donate-cta-section h2, .donate-cta-section p {
  color: var(--text-light);
}

.impact-table-wrap {
  background: var(--bg-white);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  margin: var(--space-md) 0;
  color: var(--text-primary);
}

.impact-row {
  display: flex;
  padding: 1rem 0;
  border-bottom: 1px solid var(--bg-surface-alt);
}

.impact-row:last-child {
  border-bottom: none;
}

.impact-amount {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--brand-primary);
  width: 100px;
  flex-shrink: 0;
}

/* Footer */
footer {
  background-color: var(--bg-surface);
  padding: var(--space-xl) 0 var(--space-md);
  border-top: 1px solid var(--bg-surface-alt);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--space-lg);
  margin-bottom: var(--space-lg);
}

.footer-brand p {
  margin-top: 1rem;
  font-size: 0.95rem;
}

.footer-links h4 {
  color: var(--brand-secondary);
  font-size: 1.1rem;
  margin-bottom: 1.25rem;
}

.footer-links ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-links a {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.footer-links a:hover {
  color: var(--brand-primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-md);
  border-top: 1px solid var(--bg-surface-alt);
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.social-links {
  display: flex;
  gap: 1rem;
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(27, 58, 92, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
  padding: var(--space-md);
}

.modal-overlay.active {
  opacity: 1;
  visibility: visible;
}

.modal-content {
  background: var(--bg-white);
  border-radius: var(--radius-md);
  padding: var(--space-lg);
  max-width: 500px;
  width: 100%;
  position: relative;
  transform: translateY(20px);
  transition: transform 0.3s ease;
  box-shadow: var(--shadow-lg);
}

.modal-overlay.active .modal-content {
  transform: translateY(0);
}

.modal-close {
  position: absolute;
  top: 1rem;
  right: 1.5rem;
  font-size: 2rem;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-secondary);
}

.modal-content h3 {
  color: var(--brand-secondary);
  margin-bottom: 0.5rem;
}

.donation-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin: 1.5rem 0;
}

.donation-grid .custom-amount {
  grid-column: span 2;
}

.amt-btn {
  padding: 1rem;
  border: 1px solid var(--bg-surface-alt);
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.2s;
}

.amt-btn:hover, .amt-btn.selected {
  border-color: var(--brand-primary);
  background: rgba(196, 30, 58, 0.05); /* slightly tinted */
  color: var(--brand-primary);
}

/* Mobile Nav Drawer */
.mobile-nav-drawer {
  position: fixed;
  top: 0; right: -100%;
  width: 80%;
  max-width: 300px;
  height: 100vh;
  background: var(--bg-white);
  z-index: 200;
  box-shadow: var(--shadow-lg);
  transition: right 0.3s ease;
  padding: var(--space-lg) var(--space-md);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.mobile-nav-drawer.open {
  right: 0;
}

.mobile-nav-drawer a {
  font-size: 1.25rem;
  color: var(--text-primary);
  font-weight: 600;
}

.mobile-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  z-index: 150;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease;
}

.mobile-overlay.open {
  opacity: 1;
  visibility: visible;
}

/* Responsive */
@media (max-width: 992px) {
  h1 { font-size: 2.5rem; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .cards-grid { grid-template-columns: repeat(2, 1fr); }
  .news-card { flex: 0 0 calc(50% - 1rem); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .desktop-nav { display: none; }
  .mobile-menu-btn { display: block; }
  .cards-grid { grid-template-columns: 1fr; }
  .news-card { flex: 0 0 calc(85% - 1rem); }
  .footer-grid { grid-template-columns: 1fr; }
  .hero { min-height: 60vh; text-align: center; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; }
}

